import{_ as s,o as t,c as i,a2 as a}from"./chunks/framework.doxMM-x8.js";const k=JSON.parse('{"title":"Complete Digital Laboratory Journey","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/complete-foundation","contentType":"tutorial","prev":{"text":"Entity Archiving and Appearance Replacement","link":"/en/tutorials/entity-lifecycle"},"next":false},"headers":[],"relativePath":"en/tutorials/complete-foundation.md","filePath":"en/tutorials/complete-foundation.md"}'),n={name:"en/tutorials/complete-foundation.md"};function r(p,e,o,l,d,h){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="complete-digital-laboratory-journey" tabindex="-1">Complete Digital Laboratory Journey <a class="header-anchor" href="#complete-digital-laboratory-journey" aria-label="Permalink to &quot;Complete Digital Laboratory Journey&quot;">​</a></h1><p>Goal: build one Lab with a Member and an Agent. Import appearances, place objects, run devices, query results and archive an Entity.</p><h2 id="starting-version" tabindex="-1">Starting Version <a class="header-anchor" href="#starting-version" aria-label="Permalink to &quot;Starting Version&quot;">​</a></h2><p>Use the Foundation V1 checkout containing this chapter and migrations <code>0018</code> through <code>0028</code>. The preceding integration baseline is <code>c6c3063</code>. Keep this checkout for every chapter. All capabilities below are implemented with persistent server data and backend virtual programs.</p><p>Run commands from the repository root in Bash. You need curl, Node, pnpm, Rust and Docker. See <a href="./../getting-started/quickstart">Quick start</a>. Use disposable development data. The following operations create persistent assets, Entities and records. They are not an isolated preview.</p><p>Members need an active session. Session writes require CSRF. Agents need an active <code>lab:full</code> API key. Both callers have full Lab access and follow the same business rules.</p><ol><li><p>Install the locked dependencies.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span></code></pre></div></li><li><p>Start the development stack.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div></li><li><p>Open <a href="http://127.0.0.1:5173/lab" target="_blank" rel="noreferrer">http://127.0.0.1:5173/lab</a>.</p></li><li><p>Sign in as a Member.</p></li><li><p>Create an empty Lab named <code>Complete Foundation Lab</code>.</p><p>The object directory is empty. Lab data now persists on the server.</p></li><li><p>Open <strong>Settings → API keys</strong>.</p></li><li><p>Create a key with the <code>lab:full</code> scope.</p><p>Keep <code>pnpm dev</code> running in the development terminal. Stopping it drains Node and Web and preserves the selected data directory.</p></li><li><p>Open a second Bash terminal in the repository root.</p></li><li><p>Set the API address printed by your development stack.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LAB_API_BASE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:3000</span></span></code></pre></div></li><li><p>Read the API key without displaying it.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">read</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LAB_API_KEY</span></span></code></pre></div></li><li><p>Export the key.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LAB_API_KEY</span></span></code></pre></div></li><li><p>Query the Lab list.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --silent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --show-error</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --header</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$LAB_API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$LAB_API_BASE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/v1/lab/labs?limit=100&quot;</span></span></code></pre></div><p>Find <code>Complete Foundation Lab</code> in <code>data</code>. Its <code>id</code> is the Lab UUID. If <code>has_more=true</code>, continue with <code>next_cursor</code>.</p></li><li><p>Set that UUID as <code>LAB_ID</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LAB_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;lab-uuid&gt;&#39;</span></span></code></pre></div></li></ol><p>Use this second terminal and the same <code>LAB_ID</code> for the remaining commands. Replace placeholder UUIDs with response values.</p><h2 id="build-and-operate-one-world" tabindex="-1">Build And Operate One World <a class="header-anchor" href="#build-and-operate-one-world" aria-label="Permalink to &quot;Build And Operate One World&quot;">​</a></h2><p>The scripts are the complete requests from the preceding chapters. Their assertions check the public HTTP results.</p><ol><li><p>Import the repository&#39;s Draco fixture as an Agent.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/lab/import-asset.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/fixtures/lab/cube-draco.glb</span></span></code></pre></div><p>Record the returned <code>id</code> and <code>representation_id</code>. The downloaded bytes match the uploaded SHA-256.</p></li><li><p>Open <strong>Asset library</strong> in the Member&#39;s browser.</p></li><li><p>Import <code>tests/fixtures/lab/cube-basis.glb</code>.</p></li><li><p>Publish the asset.</p><p>The library contains both imports and the built-in categories. Use the repository fixtures for this exercise. Supply accurate source and license metadata for your own files.</p></li><li><p>Open the same Lab.</p></li><li><p>Register <code>Member model</code> from <strong>Custom model · 1.0</strong>, using the Basis asset appearance.</p></li><li><p>Register a static Environment from <strong>Laboratory space · 1.0</strong>.</p></li><li><p>Register independent descriptive Robots as an Agent.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/lab/register-world.mjs</span></span></code></pre></div><p><code>Robot A</code> and <code>Robot B</code> have different Entity identities. Their declared actions return <code>422 lab.capability_not_implemented</code>.</p></li><li><p>Add the bench, Labware and explicit relationships.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/lab/edit-layout.mjs</span></span></code></pre></div><p>The script reuses <code>LAB_ID</code>. It checks manual provenance, conflicts, independent copies, multiple nodes and remove/restore.</p></li><li><p>Run two independent lights.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/lab/control-lights.mjs</span></span></code></pre></div><p>The script checks observations, same-key retries, changed-parameter rejection and retained readings after Stop.</p></li><li><p>Run two independent temperature sources.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/lab/observe-temperature.mjs</span></span></code></pre></div><p>Each reading has <code>degC</code>, timestamps, source and freshness. One stopped source expires while the other continues. Explicit startup creates a new Run.</p></li><li><p>Run two centrifuge Tasks.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/lab/run-centrifuges.mjs</span></span></code></pre></div><p>One Task completes after preparation, six seconds at target and deceleration. The other becomes cancelled after Stop and deceleration. Both devices return to idle. Record the first <code>entity_id</code>.</p></li><li><p>Read a world snapshot through the subscription.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/lab/observe-world.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --once</span></span></code></pre></div><p>The output identifies a persistent world version. Service readiness remains separate from that version.</p></li><li><p>Set the completed centrifuge Entity UUID.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LAB_ENTITY_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;first-centrifuge-entity-uuid&gt;&#39;</span></span></code></pre></div></li><li><p>Query its retained records.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/lab/query-history.mjs</span></span></code></pre></div><p>The completed Task contains its result. Observations, Commands and events have their own timestamps. A <code>gap</code> identifies unavailable earlier history.</p></li></ol><h2 id="recover-a-draft-and-a-device" tabindex="-1">Recover A Draft And A Device <a class="header-anchor" href="#recover-a-draft-and-a-device" aria-label="Permalink to &quot;Recover A Draft And A Device&quot;">​</a></h2><p>Use the selected centrifuge and an independent browser signed in to the same deployment. Its Task has ended, but its program still runs.</p><ol><li><p>Open the same Lab in the second browser.</p></li><li><p>Select the centrifuge in the first browser.</p></li><li><p>Select <strong>Edit layout</strong>.</p></li><li><p>Set <strong>X (m)</strong> to <code>2.25</code>.</p></li><li><p>Disconnect the first browser&#39;s network.</p><p><strong>Disconnected</strong> appears. The last world and the <code>2.25</code> draft remain visible.</p></li><li><p>Restore its network.</p><p><strong>Live</strong> returns. The draft still contains <code>2.25</code>.</p></li><li><p>Save the layout.</p><p>Both browsers and the API now show the saved Placement. Registered relationships keep their meaning and provenance.</p></li><li><p>Remove the device&#39;s Scene Node.</p></li><li><p>Save the layout.</p><p>The Entity and retained Run, Task and result remain queryable.</p></li><li><p>Select <strong>Unplaced objects only</strong>.</p></li><li><p>Select the device.</p></li><li><p>Add another representation of the same object.</p></li><li><p>Save the layout.</p><p>A new node represents the original Entity. Device and record identities remain unchanged.</p></li></ol><p>Unsaved drafts survive connection recovery and Lab switching in the current page. They do not survive leaving or refreshing that page. Save before refresh. For <code>409 lab.layout_conflict</code>, use <strong>Reload and keep draft</strong>, then <strong>Retry save</strong>. See <a href="./edit-layout">layout recovery</a>.</p><h2 id="archive-and-keep-the-result" tabindex="-1">Archive And Keep The Result <a class="header-anchor" href="#archive-and-keep-the-result" aria-label="Permalink to &quot;Archive And Keep The Result&quot;">​</a></h2><p>An active Run or unfinished Task blocks archive and definition changes. A Stop command does not end a centrifuge Task until deceleration finishes.</p><ol><li><p>Select <strong>Stop program</strong> on the completed centrifuge.</p></li><li><p>Set the imported Draco representation UUID.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LAB_REPRESENTATION_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;draco-representation-uuid&gt;&#39;</span></span></code></pre></div></li><li><p>Set its Asset UUID.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LAB_ASSET_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;draco-asset-uuid&gt;&#39;</span></span></code></pre></div></li><li><p>Run the lifecycle requests.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/lab/manage-entity.mjs</span></span></code></pre></div><p>The script checks running rejection, appearance replacement, explicit definition selection, archive and reference protection. The Entity keeps its completed Task and result. Old Runs retain their original definition and source.</p></li><li><p>Open <strong>Archived objects</strong> in either browser.</p></li><li><p>Select the archived Entity.</p></li><li><p>Query its Task or history through the same public paths.</p><p>New program startup returns <code>409 lab.entity_archived</code>. The viewport hides archived nodes. Their saved data and asset references remain. An arbitrary GLB does not acquire a rotor mapping.</p></li></ol><h2 id="reproduce-the-reference-load" tabindex="-1">Reproduce The Reference Load <a class="header-anchor" href="#reproduce-the-reference-load" aria-label="Permalink to &quot;Reproduce The Reference Load&quot;">​</a></h2><p>These checks create disposable services on free ports. They do not use development data. Each command removes its resources when it ends. Existing limits remain enabled.</p><p>The two browser commands each create PostgreSQL, Redis, object-storage and mail services. Their separate stacks keep preceding requests outside the reference load&#39;s per-IP rate-limit window.</p><ol><li><p>Run the complete journey.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --experimental-strip-types</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/e2e-server.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/e2e/lab-foundation.spec.ts</span></span></code></pre></div></li><li><p>Run the reference load.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">E2E_LAB_REFERENCE_LOAD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --experimental-strip-types</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/e2e-server.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/e2e/lab-reference-load.spec.ts</span></span></code></pre></div></li><li><p>Run the deterministic Lab HTTP budgets.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> perf_lab</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lab_sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lab_history</span></span></code></pre></div></li></ol><p>The reference scene contains 100 Entities and 100 placed, unarchived nodes. Twenty temperature programs target one report per second. Two Chromium browsers load the same Lab. Seventy-seven model nodes share two independent uploaded assets: Draco geometry and a Basis texture fixture.</p><p>The report records each device&#39;s actual report count, model and embedded texture bytes, browser, hardware, storage, snapshots, SSE payloads and render samples. Application evidence stays in <code>.scratch/foundation-v1/application/</code>. Document browser output uses a separate directory.</p><table tabindex="0"><thead><tr><th>Contract</th><th>Bound</th></tr></thead><tbody><tr><td>World snapshot SQL statements, including Member authentication</td><td>10, independent of 1 or 100 Entities</td></tr><tr><td>SSE event</td><td>1 MiB</td></tr><tr><td>Pending SSE events</td><td>8; overflow emits resync and closes</td></tr><tr><td>Lab, asset and history page</td><td>At most 100 items</td></tr><tr><td>History response</td><td>256 KiB</td></tr><tr><td>History time range</td><td>At most 31 days</td></tr><tr><td>Entities and Scene Nodes per Lab</td><td>At most 1000 each</td></tr><tr><td>Layout body</td><td>512 KiB; at most 1000 relationships</td></tr><tr><td>Initial / asynchronous JavaScript gzip</td><td>400 / 500 KiB, checked by <code>just perf-ci</code></td></tr></tbody></table><p>The world snapshot includes the complete bounded Lab; it has no Entity cursor. Lists and history use their documented cursors. <code>scripts/perf/baselines.json</code> records deterministic budgets. The slow-client Router check verifies backlog behavior independently of browser timing.</p><p>FPS, HTTP latency and memory samples describe this browser and hardware only. They are not cross-machine thresholds or proof of a memory leak. The fixtures are small. These results do not predict behavior for large scanned models or large textures.</p><h2 id="continue-to-physical-equipment" tabindex="-1">Continue To Physical Equipment <a class="header-anchor" href="#continue-to-physical-equipment" aria-label="Permalink to &quot;Continue To Physical Equipment&quot;">​</a></h2><p>Foundation V1 delivers persistent worlds, built-in virtual programs, shared Member/Agent APIs, recovery, history and lifecycle operations. The accepted preview supplies the visual baseline; production has no time multiplier or scenario toolbar.</p><p>Physical protocol integration, robot motion, user code, autonomous experiment planning and scientific simulation remain future scope. Register physical equipment as a separate Entity. Keep simulated and physical observations and records separate. A future adapter must preserve source identity, per-property time/quality, command idempotency and interrupted-Run recovery. See <a href="./../architecture/lab-word">product scope</a> and <a href="https://github.com/CaiZongyuan/labworld/blob/350afb740891d370b795a660e5ca94eceb5997bd/docs/adr/0007-separate-simulated-and-physical-entity-identities.md" target="_blank" rel="noreferrer">ADR 0007</a>.</p><hr><p>Source version：<code>350afb740891</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/350afb740891d370b795a660e5ca94eceb5997bd/docs/tutorials/complete-foundation.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,32)])])}const u=s(n,[["render",r]]);export{k as __pageData,u as default};
